package site.rekadev.rekaqueue.notifier;import android.content.*;public class BootReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){android.content.SharedPreferences p=c.getSharedPreferences("reka",Context.MODE_PRIVATE);if("kiosk".equals(p.getString("device_mode",""))&&!p.getString("server","").isEmpty()){try{Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);c.startActivity(open);}catch(Exception ignored){}}else if(p.contains("token"))QueueService.start(c);}}
